char* infixToPrefix(char* s) {
    int n = strlen(s);
    char* result = (char*)malloc(n * 2); 
    int resIndex = 0;
    char st[100];
    int top = -1;

    // scan from right to left
    for (int i = n - 1; i >= 0; i--) {
        char c = s[i];

        if (isalnum(c)) {
            result[resIndex++] = c;
        }
        else if (c == ')') {
            st[++top] = c;
        }
