                st.length > 0 &&
                st[st.length - 1] !== '(' &&
                (precedence(st[st.length - 1]) > precedence(c) ||
                (precedence(st[st.length - 1]) === precedence(c) && isRightAssociative(c)))
            ) {
                result += st.pop();
            }
            st.push(c);
        }
    }

    while (st.length > 0) {
        result += st.pop();
    }

    // reverse result → prefix
    return result.split('').reverse().join('');
}

